// Security headers for responses generated by the Worker (/api/*).
// Static assets get theirs from site/static/_headers, because Cloudflare does not apply _headers to
// Worker responses. The shared part must stay identical to the "/*" block there; tests/e2e/headers.spec.ts
// asserts both against one expected table.

export const COMMON_HEADERS: Readonly<Record<string, string>> = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy":
    "accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=(), browsing-topics=()",
  "Cross-Origin-Opener-Policy": "same-origin",
  "Cross-Origin-Resource-Policy": "same-origin",
  "X-Frame-Options": "DENY",
  // Until LP-go nothing on any host may be indexed.
  "X-Robots-Tag": "noindex, nofollow",
};

export const API_HEADERS: Readonly<Record<string, string>> = {
  ...COMMON_HEADERS,
  "Content-Security-Policy": "default-src 'none'; frame-ancestors 'none'",
  "Cache-Control": "no-store",
};

export function apiJson(status: number, body: unknown, extra: Record<string, string> = {}): Response {
  const headers = new Headers(API_HEADERS);
  headers.set("Content-Type", "application/json; charset=utf-8");
  for (const [name, value] of Object.entries(extra)) headers.set(name, value);
  return new Response(JSON.stringify(body), { status, headers });
}
